<script setup>
import { onMounted, ref } from 'vue'; import { getDashboard } from '../api/video.js'; import StatCard from '../components/StatCard.vue'; import BaseChart from '../components/BaseChart.vue'
const data=ref({stats:{},behaviors:{},anomalies:{},trend:[]}); onMounted(async()=>data.value=await getDashboard())
const axis={axisLine:{lineStyle:{color:'#334155'}},axisLabel:{color:'#94a3b8'},splitLine:{lineStyle:{color:'#1e293b'}}}
const bar=()=>({tooltip:{},grid:{left:42,right:16,top:20,bottom:32},xAxis:{...axis,type:'category',data:Object.keys(data.value.behaviors)},yAxis:{...axis,type:'value'},series:[{type:'bar',data:Object.values(data.value.behaviors),itemStyle:{color:'#22c55e',borderRadius:[3,3,0,0]}}]})
const pie=()=>({tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#94a3b8'}},series:[{type:'pie',radius:['45%','70%'],data:Object.entries(data.value.anomalies).map(([name,value])=>({name,value})),color:['#ef4444','#f59e0b','#38bdf8']} ]})
const trend=()=>({tooltip:{trigger:'axis'},grid:{left:42,right:16,top:20,bottom:32},xAxis:{...axis,type:'category',data:data.value.trend.map(x=>x.date)},yAxis:{...axis,type:'value'},series:[{type:'line',smooth:true,data:data.value.trend.map(x=>x.count),lineStyle:{color:'#38bdf8'},areaStyle:{color:'rgba(56,189,248,.12)'},symbolSize:7}]})
</script>
<template><div class="page"><div class="stat-grid"><StatCard label="视频总数" :value="data.stats.videos||0" note="已入库视频"/><StatCard label="分析任务" :value="data.stats.tasks||0" note="已完成处理" tone="blue"/><StatCard label="人物数量" :value="data.stats.persons||0" note="稳定身份" tone="amber"/><StatCard label="异常事件" :value="data.stats.anomalies||0" note="需关注事件" tone="red"/></div><div class="chart-grid"><section class="panel"><header>行为分布</header><BaseChart :option="bar()"/></section><section class="panel"><header>异常事件统计</header><BaseChart :option="pie()"/></section><section class="panel wide"><header>视频分析趋势</header><BaseChart :option="trend()"/></section></div></div></template>
